import type { jsPDF } from 'jspdf';
// Original AI-generated Pak Usop calligraphy, embedded for offline browser/server parity.
const signature = 'data:image/png;base64,';
export function drawInvoiceSignature(doc: jsPDF): void {
  doc.addImage(signature, 'PNG', 220, 147, 60, 20, 'pak-usop-signature', 'FAST');
  doc.setDrawColor(194, 147, 45);
  doc.setLineWidth(0.2);
  doc.line(220, 168, 280, 168);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8);
  doc.setTextColor(80, 66, 45);
  doc.text('Pak Usop', 250, 172, {align:'center'});
}
